pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }

    const PREFIX: &str = "{\"v\":2,\"hello\":\"";
    if let Some(value) = bytes.strip_prefix(PREFIX).and_then(|value| value.strip_suffix("\"}")) {
        return decode_json_string(value).map(Msg::Hello);
    }

    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!(r#"{{"v":2,"hello":"{}"}}"#, encode_json_string(value)),
    }
}

fn encode_json_string(value: &str) -> String {
    let mut encoded = String::with_capacity(value.len());
    for character in value.chars() {
        match character {
            '"' => encoded.push_str("\\\""),
            '\\' => encoded.push_str("\\\\"),
            '\n' => encoded.push_str(r#"\n"#),
            '\r' => encoded.push_str(r#"\r"#),
            '\t' => encoded.push_str(r#"\t"#),
            character if character.is_control() => {
                encoded.push_str(&format!(r#"\u{:04x}"#, character as u32));
            }
            character => encoded.push(character),
        }
    }
    encoded
}

fn decode_json_string(value: &str) -> Result<String, String> {
    let mut decoded = String::with_capacity(value.len());
    let mut characters = value.chars();
    while let Some(character) = characters.next() {
        if character != '\\' {
            decoded.push(character);
            continue;
        }

        match characters.next() {
            Some('"') => decoded.push('"'),
            Some('\\') => decoded.push('\\'),
            Some('/') => decoded.push('/'),
            Some('b') => decoded.push('\u{0008}'),
            Some('f') => decoded.push('\u{000c}'),
            Some('n') => decoded.push('\n'),
            Some('r') => decoded.push('\r'),
            Some('t') => decoded.push('\t'),
            _ => return Err("invalid hello envelope".into()),
        }
    }
    Ok(decoded)
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    fn roundtrip(msg: &Msg) -> Msg {
        decode(&encode(msg)).unwrap()
    }

    #[test]
    fn ping_encode_roundtrip() {
        assert!(matches!(roundtrip(&Msg::Ping), Msg::Ping));
    }

    #[test]
    fn hello_uses_v2_envelope_and_roundtrips() {
        let message = Msg::Hello("hello".into());
        assert_eq!(encode(&message), r#"{"v":2,"hello":"hello"}"#);
        assert!(matches!(decode(r#"{"v":2,"hello":"hello"}"#), Ok(Msg::Hello(value)) if value == "hello"));
    }
}
